/**
 * Writes the vectors the Go platform libraries are tested against, from the
 * TypeScript code that is the spec. Run from the repo root:
 *
 *   node_modules/.bin/jiti server/testdata/vectors/generate.ts
 *
 * Also writes `internal/platform/bs/table.go` from `nepali-date-converter`'s own
 * table, so the Go calendar can never hold a month length TS does not.
 */

import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { createRequire } from "node:module";

import * as bs from "../../../packages/shared/src/calendar/bs";
import * as night from "../../../packages/shared/src/night/night-window";
import * as plans from "../../../packages/shared/src/plans/catalog";
import * as lifetime from "../../../packages/shared/src/plans/lifetime";
import { createJiti } from "jiti";

import { configVectors } from "./config";

const here = join(process.cwd(), "server");
const iso = (d: Date) => d.toISOString();
const MS_DAY = 86_400_000;

/** A value, or `{ error: true }` where TS throws. */
function attempt<T>(run: () => T): T | { error: true } {
  try {
    return run();
  } catch {
    return { error: true };
  }
}

function writeJson(name: string, value: unknown) {
  writeFileSync(join(here, "testdata/vectors", name), `${JSON.stringify(value, null, 1)}\n`);
}

/* ------------------------------------------------------------------ table */

const require = createRequire(join(process.cwd(), "packages/shared/package.json"));
const umd = readUmd();

function readUmd(): string {
  const path = require.resolve("nepali-date-converter");
  return require("node:fs").readFileSync(path, "utf8") as string;
}

const tableSource = /var dateConfigMap = (\{[\s\S]*?\n {4}\});/.exec(umd)?.[1];
if (!tableSource) throw new Error("dateConfigMap not found in nepali-date-converter");
const table = Function(`return ${tableSource}`)() as Record<string, Record<string, number>>;
const years = Object.keys(table).map(Number).sort((a, b) => a - b);

writeFileSync(
  join(here, "internal/platform/bs/table.go"),
  [
    "// Code generated by testdata/vectors/generate.ts from nepali-date-converter. DO NOT EDIT.",
    "",
    "package bs",
    "",
    `// monthDays[y-${years[0]}][m] is the length of BS month m+1 of year y.`,
    `var monthDays = [...][12]int{`,
    ...years.map((y) => `\t{${Object.values(table[String(y)]).join(", ")}}, // ${y}`),
    "}",
    "",
  ].join("\n"),
);

/* --------------------------------------------------------------- instants */

const instants: Date[] = [];
for (let y = 2070; y <= 2090; y++) {
  for (let m = 1; m <= 12; m++) {
    const start = attempt(() => bs.fromBs({ day: 1, month: m, year: y }));
    if ("error" in start) continue;
    // Each side of the Nepal midnight that opens the month, and the day before.
    const nepalMidnight = start.getTime() - bs.HOSTEL_UTC_OFFSET_MINUTES * 60_000;
    for (const offset of [-MS_DAY, -1, 0, 1, 6 * 3_600_000, 18 * 3_600_000 + 14 * 60_000]) {
      instants.push(new Date(nepalMidnight + offset));
    }
  }
}
// A fixed pseudo-random spread so the file is stable between runs.
let seed = 20831;
const next = () => (seed = (seed * 1_103_515_245 + 12_345) % 2_147_483_648) / 2_147_483_648;
for (let i = 0; i < 400; i++) {
  instants.push(new Date(Date.UTC(2013, 3, 14) + Math.floor(next() * 77 * 365 * MS_DAY)));
}
instants.push(new Date(Date.UTC(1943, 3, 13, 18, 15)), new Date(Date.UTC(2034, 3, 13)));

const instantCases = instants.map((at) => ({
  at: iso(at),
  toBs: attempt(() => bs.toBs(at)),
  calendarDay: iso(bs.hostelCalendarDay(at)),
  dayEnd: [-1, 0, 3].map((plus) => iso(bs.hostelDayEnd(at, plus))),
  dayParts: bs.hostelDayParts(at),
  period: attempt(() => bs.bsPeriodOf(at)),
  monthStart: attempt(() => iso(bs.bsMonthStart(at))),
  date: bs.formatBsDate(at),
  time: bs.formatHostelTime(at),
  dateTime: bs.formatHostelDateTime(at),
  dayMonth: bs.formatBsDayMonth(at),
  fiscalYear: bs.bsFiscalYear(at),
  monthsEnd: [1, 3, 12].map((n) => attempt(() => iso(bs.bsMonthsEnd(at, n)))),
  cyclePeriod: [1, 20, 32].map((day) => attempt(() => bs.bsCyclePeriodOf(at, day))),
  nightKey: night.nightKey(at),
  nightEndsAt: iso(night.nightEndsAt(night.nightKey(at))),
}));

const pairs = instants.slice(0, 300).map((from, i) => {
  const to = instants[(i * 7 + 3) % instants.length];
  return {
    from: iso(from),
    to: iso(to),
    daysBetween: bs.hostelDaysBetween(from, to),
    dayRange: attempt(() => bs.formatBsDayRange(from, to)),
    sameNight: night.isSameNight(from, to),
  };
});

/* ---------------------------------------------------------------- periods */

const periodCases: unknown[] = [];
for (let y = 2069; y <= 2091; y++) {
  for (let m = 1; m <= 12; m++) {
    const key = bs.formatPeriodKey(y, m);
    const bounds = (b: ReturnType<typeof bs.bsPeriodBounds>) => ({
      daysInMonth: b.daysInMonth,
      end: iso(b.end),
      lastDay: iso(b.lastDay),
      start: iso(b.start),
    });
    periodCases.push({
      period: key,
      bounds: attempt(() => bounds(bs.bsPeriodBounds(key))),
      daysInMonth: attempt(() => bs.bsDaysInMonth(y, m)),
      cycle: [1, 15, 20, 32].map((day) => attempt(() => bounds(bs.bsCycleBounds(key, day)))),
      add: [-13, -1, 1, 12, 25].map((d) => bs.addBsMonths(key, d)),
      label: bs.formatBsPeriod(key),
      month: bs.formatBsPeriodMonth(key),
      year: bs.formatBsPeriodYear(key),
    });
  }
}

const keyStrings = [
  "2083-05", " 2083-05 ", "2026-09", "2069-12", "2070-01", "2083-00", "2083-13",
  "2083-5", "83-05", "", "abcd-ef", "2083-05-01", "2099-01",
];
const keyCases = keyStrings.map((key) => ({
  key,
  parts: bs.periodParts(key),
  isBs: bs.isBsPeriod(key),
  label: bs.formatBsPeriod(key),
}));

const betweenCases = [
  ["2083-01", "2083-12", 120],
  ["2083-05", "2083-05", 120],
  ["2083-06", "2083-05", 120],
  ["2070-01", "2083-05", 120],
  ["2080-11", "2081-02", 2],
  ["bad", "2083-05", 120],
].map(([from, to, cap]) => ({
  from,
  to,
  cap,
  periods: attempt(() => bs.bsPeriodsBetween(from as string, to as string, cap as number)),
}));

writeJson("bs.json", {
  instants: instantCases,
  pairs,
  periods: periodCases,
  keys: keyCases,
  between: betweenCases,
});

/* ------------------------------------------------------------------ night */

const promptTimes = [
  "20:00", "17:00", "16:59", "23:45", "23:46", "21:30", "18:00", "08:00", "",
  "2000", " 20:00 ", "24:00", "19:7",
];
const nightInstants = Array.from({ length: 96 }, (_, i) =>
  new Date(Date.UTC(2026, 8, 8, 11, 15) + i * 15 * 60_000),
);

writeJson("night.json", {
  prompts: promptTimes.map((value) => ({
    value,
    parsed: night.parsePromptTime(value),
    askingEndsAt: night.askingEndsAt(value),
  })),
  format: [0, 59, 1020, 1425, 1439].map((minute) => ({
    minute,
    text: night.formatPromptTime(minute),
  })),
  repeat: [null, 0, 15, 30, 45, 60, 90].map((value) => ({
    value,
    every: night.repeatEveryMinutes(value),
  })),
  rounds: nightInstants.flatMap((at) =>
    ["20:00", "18:00", "23:45", "21:30"].flatMap((prompt) =>
      [15, 30, 60, 45].map((every) => ({
        at: iso(at),
        prompt,
        every,
        round: night.promptRound(prompt, every, at),
      })),
    ),
  ),
  current: [
    ["2026-09-08T17:45:00.000Z", "2026-09-08T19:00:00.000Z"],
    ["2026-09-08T11:14:00.000Z", "2026-09-08T11:16:00.000Z"],
    [null, "2026-09-08T19:00:00.000Z"],
    ["not a date", "2026-09-08T19:00:00.000Z"],
  ].map(([checkedAt, now]) => ({
    checkedAt,
    now,
    current: night.isCurrentNight(checkedAt, new Date(now as string)),
  })),
});

console.log(`bs.json: ${instantCases.length} instants, ${periodCases.length} periods; night.json written`);

/* ---------------------------------------------------------- money + plans */

